L000062	\title{Irreversible thermalization vs reversible dynamics mediated by anomalous correlators: Wave turbulence theory and experiments in optical fibers}
L000063	\author{T. Torres$^{1}$, J. Garnier$^{2}$, L. Zanaglia$^{3}$, M. Ferraro$^{1,4}$, C. Michel$^{3}$, V. Doya$^{3}$,\\ J. Fatome$^{1}$, B. Kibler$^{1}$, S. Wabnitz$^{5}$, A. Picozzi$^{1}$, G. Millot$^{1}$}
L000064	\affiliation{$^{1}$ Universit\'e Bourgogne Europe, CNRS, Laboratoire Interdisciplinaire Carnot de Bourgogne ICB UMR 6303, 21000 Dijon, France}
