L001902	\section*{ Supplementary information on the article:}
L001903	
L001904	\section{Thermalization: Derivation of a reduced wave turbulence kinetic equation for simulations}
L001905	
L001906	In Fig.~1 (main text), we report numerical simulations of the WT KE~(2) (main text). The one-dimensional interaction allows the KE~(2)  (main text) to be written in a simplified form, which greatly improves the efficiency of its numerical integration. In the following, we derive the simplified version of KE~(2) (main text).
L001907	
L001908	We start from the coherently coupled NLSE (1) (main text):
L001909	\begin{eqnarray}
L001910	i\partial_z u_x &=& - \beta \partial_{tt} u_x + \alpha u_x + \gamma (|u_x|^2+ \kappa |u_y|^2)u_x + \gamma \rho u_x^* u_y^2,
L001911	\label{eq:nls_x}\\
L001912	i\partial_z u_y  &=& - \beta \partial_{tt} u_y - \alpha u_y + \gamma(|u_y|^2+ \kappa |u_x|^2)u_y  + \gamma \rho u_y^* u_x^2.
L001913	\label{eq:nls_y}
L001914	\end{eqnarray}
L001915	The corresponding dispersion relations read $k_{x}(\omega)=\beta \omega^2+\alpha$ and $k_{y}(\omega)=\beta \omega^2-\alpha$.
L001916	The NLSE conserves the power (particle number) $N=N_x+N_y$, with $N_\mu=\frac{1}{T}\int_0^T |u_\mu|^2 dt$ ($\mu=x,y$), where $T$ denotes the size of the numerical window. It also conserves the Hamiltonian  $H = E+U$, which has a linear and a nonlinear contribution. The linear contribution $E=E_k+E_c$ can be split into a kinetic contribution and a resonant coupling contribution:
L001917	\begin{eqnarray}
L001918	E_k=\frac{1}{T}  \int_0^T  \beta (|\partial_t u_x|^2+|\partial_t u_y|^2)dt,
L001919	\quad
L001920	E_c=\frac{1}{T}  \int_0^T  \alpha (|u_x|^2-|u_y|^2)dt.
L001921	\label{eq:E_lin}
L001922	\end{eqnarray}
L001923	The  nonlinear contribution reads
L001924	\begin{eqnarray}
L001925	U=\frac{1}{T} \int_0^T \frac{\gamma}{2}\big(|u_x|^4+|u_y|^4\big) + \gamma \kappa |u_x|^2 |u_y|^2
L001926	+\frac{\gamma \rho}{2} \big(u_x^{* 2} u_y^2 + u_x^{2} u_y^{* 2}\big) dt.
L001927	\end{eqnarray}
L001928	\medskip
L001929	Following the standard wave turbulence theory \cite{zakharov92,zakharov04,nazarenko11}, we derive from the vector NLSE (\ref{eq:nls_x}-\ref{eq:nls_y}) the following kinetic equations
L001930	
L001931	\begin{align}
L001932	\partial_z n_{x}(\omega,z) &= \kappa^2 {\cal C}oll_i[n_{x},n_{y}] + \rho^2 {\cal C}oll_c[n_{x},n_{y}],
L001933	\\
L001934	\partial_z n_{y}(\omega,z) &= \kappa^2 {\cal C}oll_i[n_{y},n_{x}] + \rho^2 {\cal C}oll_c[n_{y},n_{x}],
L001935	\end{align}
L001936	where $\left< {\tilde u}_\mu(\omega_1,z) {\tilde u}_\mu^*(\omega_2,z) \right>=2\pi n_\mu(\omega_1,z) \delta(\omega_1-\omega_2)$ under the assumption of homogeneous statistics, where ${\tilde u}_\mu(\omega,z)=\int u_\mu(t,z) \exp(-i\omega t) dt$ is the Fourier transform, for $\mu=x,y$.
L001937	
L001938	
L001939	
L001940	
L001941	The collision term for the non-resonant interaction reads:
L001942	\begin{eqnarray}
L001943	&&\hspace*{-0.2in}
L001944	{\cal C}oll_i[n_{x},n_{y}] = \frac{ \gamma^2}{2\pi} \iiint d\omega_{1-3} \,
L001945	 n_{x}(\omega_1) \, n_{y}(\omega_2)\,n_{y}(\omega_3)\,n_{x}(\omega)  \left( n_{x}^{-1}(\omega)+n_{y}^{-1}(\omega_3)-n_{y}^{-1}(\omega_2)-n_{x}^{-1}(\omega_1)\right) \nonumber\\
L001946	&&\hspace*{2.3in}
L001947	\times \, \delta\big(k_x(\omega_1)+k_y(\omega_2)-k_y(\omega_3)-k_x(\omega)\big) \
L001948	\delta(\omega_1+\omega_2-\omega_3-\omega),
L001949	\label{eq:wtcollu}\\
L001950	&&\hspace*{-0.2in}
L001951	{\cal C}oll_i[n_{y},n_{x}] = \frac{ \gamma^2}{2\pi} \iiint d\omega_{1-3} \,
L001952	 n_{y}(\omega_1) \, n_{x}(\omega_2)\,n_{x}(\omega_3)\,n_{y}(\omega)  \left( n_{y}^{-1}(\omega)+n_{x}^{-1}(\omega_3)-n_{x}^{-1}(\omega_2)-n_{y}^{-1}(\omega_1)\right) \nonumber \\
L001953	&&\hspace*{2.3in}
L001954	\times \, \delta\big(k_y(\omega_1)+k_x(\omega_2)-k_x(\omega_3)-k_y(\omega)\big) \
L001955	\delta(\omega_1+\omega_2-\omega_3-\omega),
L001956	\label{eq:wtcollv}
L001957	\end{eqnarray}
L001958	with $d\omega_{1-3}=d\omega_1 d\omega_2 d\omega_3$.
L001959	The collision term for the resonant interaction reads:
L001960	\begin{eqnarray}
L001961	&&\hspace*{-0.2in}
L001962	{\cal C}oll_c[n_{x},n_{y}] = \frac{ 2\gamma^2}{2\pi} \iiint d\omega_{1-3} \,
L001963	 n_{y}(\omega_1) \, n_{y}(\omega_2)\,n_{x}(\omega_3)\,n_{x}(\omega)  \left( n_{x}^{-1}(\omega)+n_{x}^{-1}(\omega_3)-n_{y}^{-1}(\omega_2)-n_{y}^{-1}(\omega_1)\right) \nonumber\\
L001964	&&\hspace*{2.3in}
L001965	\times \, \delta\big(k_y(\omega_1)+k_y(\omega_2)-k_x(\omega_3)-k_x(\omega)\big) \
L001966	\delta(\omega_1+\omega_2-\omega_3-\omega),
L001967	\label{eq:wtcollu}\\
L001968	&&\hspace*{-0.2in}
L001969	{\cal C}oll_c[n_{y},n_{x}] = \frac{ 2\gamma^2}{2\pi} \iiint d\omega_{1-3} \,
L001970	 n_{x}(\omega_1) \, n_{x}(\omega_2)\,n_{y}(\omega_3)\,n_{y}(\omega)  \left( n_{y}^{-1}(\omega)+n_{y}^{-1}(\omega_3)-n_{x}^{-1}(\omega_2)-n_{x}^{-1}(\omega_1)\right) \nonumber \\
L001971	&&\hspace*{2.3in}
L001972	\times \, \delta\big(k_x(\omega_1)+k_x(\omega_2)-k_y(\omega_3)-k_y(\omega)\big) \
L001973	\delta(\omega_1+\omega_2-\omega_3-\omega).
L001974	\label{eq:wtcollv}
L001975	\end{eqnarray}
L001976	Note that, because of the degenerate resonances inherent to the purely one-dimensional problem considered here, the collision term describing the self-interaction (first nonlinear term in Eqs.(\ref{eq:nls_x}-\ref{eq:nls_y})) vanishes identically, see \cite{zakharov92,zakharov04,nazarenko11}.
L001977	We focus on the analysis of the resonant collision term.
L001978	Two integrals can be computed owing to the Dirac $\delta-$functions, which gives:
L001979	\begin{eqnarray}
L001980	&&\hspace*{-0.2in}
L001981	\partial_z n_{x}(\omega,z) = \kappa^2 {\cal C}oll_i[n_{x},n_{y}] + \frac{2 \rho^2 \gamma^2}{4\pi |\beta|} \int
L001982	 n_{y}(\omega +
L001983	 {\omega'}) \, n_{y}(\omega-\nu/{\omega'})\,n_{x}(\omega +{\omega'}-\nu/{\omega'})\,n_{x}(\omega) \nonumber\\
L001984	&&\hspace*{2.2in}
