L002142	\section{Anomalous correlator kinetic equation}
L002143	
L002144	\subsection{Derivation of Eqs.(4-5) (main text)}
L002145	
L002146	We start from the NLSE (\ref{eq:nls_x}-\ref{eq:nls_y}) and define the normal correlator
L002147	$U_\mu(t_1,t_2,z)=\left< u_\mu(t_1,z)u_\mu(t_2,z)^* \right>$ for $\mu=x,y$, and the anomalous correlator describing a correlation among the waves $u_x$ and $u_y$: $W(t_1,t_2,z)=\left< u_y(t_1,z)u_x^*(t_2,z) \right>$.
L002148	Following the usual procedure, we derive the equations for the correlators $U_\mu$ and $W$, which involve fourth-order moments of the waves that can be expanded into products of second-order moments in the weakly nonlinear regime of Gaussian statistics. Here, caution should be exercized in keeping all anomalous correlations between the waves. We obtain
L002149	\begin{align}
L002150	i\partial_z U_x^{12} =& - \beta(\partial_{t_1}^2-\partial_{t_2}^2)U_x^{12}
L002151	+ \gamma U_x^{12}[2(U_x^{11}-U_x^{22})+\kappa(U_y^{11}-U_y^{22})]
L002152	+ \gamma \kappa \big[ W^{12}(W^{11}+W^{11*}) - W^{21*}(W^{22}+W^{22*}) \big],
L002153	\nonumber \\
L002154	i\partial_z U_y^{12} =& - \beta(\partial_{t_1}^2-\partial_{t_2}^2)U_y^{12}
L002155	+\gamma U_y^{12}[2(U_y^{11}-U_y^{22})+\kappa(U_x^{11}-U_x^{22})]
L002156	+ \gamma \kappa \big[ W^{21*}(W^{11}+W^{11*}) - W^{12}(W^{22}+W^{22*}) \big],
L002157	\nonumber \\
L002158	i\partial_z W^{12} =& - \beta(\partial_{t_1}^2-\partial_{t_2}^2)W^{12}
L002159	-2\alpha W^{12}
L002160	+\gamma W^{12} \big[2(U_y^{11}-U_x^{22})+\kappa(U_x^{11}-U_y^{22})\big]
L002161	\nonumber \\
L002162	&+\gamma \kappa \big[U_x^{12}(W^{11}+W^{11*})-U_y^{12}(W^{22}+W^{22*}) \big]  ,
L002163	\nonumber
L002164	\end{align}
L002165	where  $U_\mu^{ij}=U_\mu(t_i,t_j,z)$ for $\mu=x,y$, and $W^{ij}=W(t_i,t_j,z)$.
L002166	Introducing the variables $t=(t_1+t_2)/2, \tau=t_1-t_2$, this also reads
L002167	\begin{align}
L002168	i\partial_z U_x =& - 2 \beta \partial_{t \tau} U_x + \gamma {\cal L}^{U_x} ,\\
L002169	i\partial_z U_y =& - 2 \beta \partial_{t \tau} U_y + \gamma {\cal L}^{U_y} ,\\
L002170	i\partial_z W =& - 2 \beta\partial_{t \tau}  W
L002171	-2\alpha W + \gamma {\cal L}^{W} ,
L002172	\end{align}
L002173	with the three nonlinear terms
L002174	\begin{align}
L002175	{\cal L}^{U_x} (t,\tau) =&
L002176	U_x(t,\tau) [ (2U_x+\kappa U_y)(t+\tau/2,0)-(2U_x+\kappa U_y)(t-\tau/2,0)]
L002177	\nonumber
L002178	\\
L002179	&
L002180	+ 2 \kappa \big[ W(t,\tau) W^r(t+\tau/2,0) - W(t,-\tau)^* W^r(t-\tau/2,0)  \big],\\
L002181	{\cal L}^{U_y} (t,\tau) =&
L002182	U_y(t,\tau) [ (2U_y+\kappa U_x)(t+\tau/2,0)-(2U_y+\kappa U_x)(t-\tau/2,0)]
L002183	\nonumber
L002184	\\
L002185	&
L002186	+ 2 \kappa \big[ W(t,-\tau)^* W^r(t+\tau/2,0) - W(t,\tau) W^r(t-\tau/2,0)  \big], \\
L002187	{\cal L}^W(t,\tau)=&  W(t,\tau) \big[(2U_y+\kappa U_x)(t+\tau/2,0)-(2U_x+\kappa U_y)(t-\tau/2,0)\big]
L002188	\nonumber
L002189	\\
L002190	&
L002191	+2 \kappa \big[U_x(t,\tau) W^r(t+\tau/2) -U_y (t,\tau) W^r(t-\tau/2,0) \big]  ,
L002192	\end{align}
L002193	where $W^r={\rm Re}(W)$.
L002194	We can make use of the assumption of quasi-stationary statistics, that is to say the time correlation $t_c$ (i.e. the microscopic time scale of random fluctuations) is much smaller than the macroscopic time scale $t_s$ of stationary (homogeneous) statistics. In the regime $\varepsilon = t_c/t_s \ll 1$, the three nonlinear terms can be expanded up to first order as
L002195	\begin{align}
L002196	{\cal L}^{U_x} (t,\tau) =&
L002197	U_x(t,\tau)  \tau \partial_t (2U_x+\kappa U_y)(t,0)
L002198	+ 2 \kappa  W^r(t,0)  \big[ W(t,\tau) - W(t,-\tau)^* \big]
L002199	+ \kappa \tau \partial_t W^r(t,0) \big[ W(t,\tau) + W(t,-\tau)^* \big] ,\\
L002200	{\cal L}^{U_y} (t,\tau) =&
L002201	U_y(t,\tau) \tau \partial_t  (2U_y+\kappa U_x)(t,0)
L002202	- 2 \kappa W^r(t,0)  \big[  W(t,\tau) - W(t,-\tau)^*   \big]
L002203	+  \kappa \tau \partial_t W^r(t,0)  \big[ W(t,\tau) +W(t,-\tau)^*  \big]
L002204	, \\
L002205	\nonumber
L002206	{\cal L}^W(t,\tau)=& (2-\kappa) W(t,\tau) ( U_y -U_x)(t,0)
L002207	+(2+\kappa)W(t,\tau) \frac{\tau}{2}\partial_t (U_y+U_x)(t,0) \\
L002208	&
L002209	+ 2\kappa W^r(t,0) (U_x - U_y)(t,\tau)
L002210	 +\kappa \tau \partial_t W^r(t,0) (U_x+U_y)(t,\tau) .
L002211	\end{align}
L002212	This gives
L002213	\begin{align}
L002214	i\partial_z U_x(t,\tau,z) =& - 2 \beta\partial_{t \tau} U_x +
L002215	\gamma\tau U_x \partial_t \big( 2 N_x(t) + \kappa N_y(t) \big)
L002216	-2\gamma\kappa W_0^r(t) \big( W^*(t,-\tau) - W(t,\tau) \big)\nonumber
L002217	\\
L002218	&
L002219	+ \gamma \kappa \tau \partial_t W_0^r(t) \big[ W(t,\tau) + W(t,-\tau)^* \big]  ,
L002220	\label{eq:U_x}  \\
L002221	i\partial_z U_y(t,\tau,z) =& - 2 \beta \partial_{t \tau} U_y +
L002222	\gamma\tau U_y \partial_t \big( 2 N_y(t) + \kappa N_x(t) \big)
L002223	-2\gamma\kappa W_0^r(t) \big( W(t,\tau)-W^*(t,-\tau) \big)
L002224	\nonumber
L002225	\\
L002226	& + \gamma \kappa \tau \partial_t W_0^r(t) \big[ W(t,\tau) + W(t,-\tau)^* \big] ,
L002227	\label{eq:U_y}  \\
L002228	i\partial_z W(t,\tau,z) =& - 2\beta \partial_{t \tau} W
L002229	+W\Big( \gamma(2-\kappa)\big(N_y(t)-N_x(t)\big)-2\alpha   \Big)
L002230	- 2\gamma\kappa \big( U_y-U_x \big) W_0^r(t) \nonumber \\
L002231	&+\gamma(1+\kappa/2)\tau W \partial_t \big( N_y(t)+N_x(t) \big)
L002232	+\gamma\kappa \tau \big( U_y+U_x \big) \partial_t W_0^r(t)  ,
L002233	\label{eq:W}
L002234	\end{align}
L002235	where $W_0(t,z)=W(t,\tau=0,z)$, and $N_\mu(t,z)=U_\mu(t,\tau=0,z)$.
L002236	
L002237	The equations for the normal correlator $n_\mu(t,\omega,z)=\int U_\mu(t,\tau,z) \exp(-i\omega \tau) d\tau$, and the anomalous correlator $m(t,\omega,z)=\int W(t,\tau,z) \exp(-i\omega \tau) d\tau$, are obtained by taking the Fourier transform of Eqs.(\ref{eq:U_x}-\ref{eq:W}), leading to the set of Eqs.(4-5) (main text):
L002238	\begin{align}
L002239	\partial_z n_x(\omega,t) =& - 2\beta \omega \partial_t n_x
L002240	+ \gamma \partial_t \big(2 N_x(t) + \kappa N_y(t) \big)\partial_\omega n_x
L002241	+2\gamma\kappa \partial_t M^r(t) \partial_\omega m^r(\omega,t)
L002242	+4 \gamma\kappa M^r(t) m^i(\omega,t) ,
L002243	\label{eq:nx_vl_supp} \\
L002244	\partial_z n_y(\omega,t) =& - 2 \beta\omega \partial_t n_y + \gamma \partial_t \big(2 N_y(t) + \kappa N_x(t) \big)\partial_\omega n_y
L002245	+2\gamma\kappa \partial_t M^r(t) \partial_\omega m^r(\omega,t)
L002246	-4 \gamma\kappa M^r(t) m^i(\omega,t)  ,
L002247	\label{eq:ny_vl_supp} \\
L002248	\partial_z m(\omega,t) =& -2\beta \omega \partial_t m
L002249	+\gamma(1+\kappa/2) \partial_t \big( N_x(t)+N_y(t) \big) \partial_\omega m
L002250	+\gamma\kappa \partial_t M^r(t)\partial_\omega \big( n_x+n_y \big)
L002251	\nonumber \\
L002252	&-i m \Big( \gamma(2-\kappa)\big(N_y(t)-N_x(t)\big)-2\alpha   \Big)
L002253	- 2i\gamma\kappa \big( n_x - n_y \big) M^r(t)   ,
L002254	\label{eq:m_vl_supp}
L002255	\end{align}
L002256	where $M(t,z)=W_0(t,z)=\frac{1}{2\pi}\int m(t,\omega,z)d\omega$, and ${N}_{\mu}(t,z)=\frac{1}{2\pi}\int n_{\mu}(t,\omega,z)d\omega$, while $m^{r,i}$ ($M^{r,i}$) denote the real and imaginary parts of $m$ ($M$).
L002257	
L002258	Note that the system of Eqs.(\ref{eq:nx_vl_supp}-\ref{eq:m_vl_supp}) is formally reversible in the `time' variable $z$, i.e., it is invariant under the transformation: $(z \to -z, \omega \to -\omega, m \to m^*)$.
