L002260	\subsection{Stability analysis for the emergence of phase-correlations: Derivation of Eq.(6) (main text)}
L002261	
L002262	We assume that the initial random waves $u_\mu(t,z=0)$ have a homogeneous statistics with spectra $n_\mu^0(\omega)$, and are uncorrelated with each other, so that the initial anomalous correlator is zero, $m(\omega,t,z=0)=0$. We perform a linear stability analysis of Eqs.(\ref{eq:nx_vl_supp}-\ref{eq:m_vl_supp}) around this solution with
L002263	\begin{align}
L002264	n_\mu(t,\omega,z) &= n_\mu^0(\omega) + \delta n_\mu(t,\omega,z), \quad \mu=x,y ,
L002265	\label{eq:pert_n}\\
L002266	m(t,\omega,z) &= \delta m(t,\omega,z),
L002267	\label{eq:pert_m}
L002268	\end{align}
L002269	with $\delta n_\mu(t,\omega,z) \ll n_\mu^0(\omega)$ and $|\delta m(t,\omega,z)| \ll n_\mu^0(\omega)$.
L002270	Introducing (\ref{eq:pert_n}-\ref{eq:pert_m}) into Eqs.(\ref{eq:nx_vl_supp}-\ref{eq:m_vl_supp}), we obtain after linearization
L002271	\begin{align}
L002272	\partial_z \delta n_x(t,\omega) =& - 2\beta \omega \partial_t \delta n_x + \gamma\partial_\omega n_x^0 \partial_t \big(2 \delta N_x(t) + \kappa \delta N_y(t) \big),
L002273	\label{eq:deltanx_vl_supp} \\
L002274	\partial_z \delta n_y(t,\omega) =& - 2 \beta\omega \partial_t \delta n_y + \gamma\partial_\omega n_y^0 \partial_t \big(2 \delta N_y(t) + \kappa \delta N_x(t) \big),
L002275	\label{eq:deltany_vl_supp} \\
L002276	\partial_z \delta m(t,\omega) =& -2\beta \omega \partial_t \delta m
L002277	-i \delta m \Big( \gamma(2-\kappa)\big(N_y^0-N_x^0\big)-2\alpha   \Big)
L002278	- 2i\gamma\kappa \big( n_x^0 - n_y^0 \big) \delta M^r(t) \nonumber \\
L002279	& +\gamma\kappa\partial_\omega \big( n_x^0+n_y^0 \big) \partial_t \delta M^r(t),
L002280	\label{eq:deltam_vl_supp}
L002281	\end{align}
L002282	where $N_\mu^0 = \frac{1}{2\pi}\int n_\mu^0(\omega) d\omega$, $\delta N_\mu(t,z) = \frac{1}{2\pi}\int \delta n_\mu(t,\omega,z) d\omega$, $\delta M(t,z) = \frac{1}{2\pi}\int \delta m(t,\omega,z) d\omega$. Note that the evolution of $\delta n_\mu$ in (\ref{eq:deltanx_vl_supp}-\ref{eq:deltany_vl_supp}) is decoupled from the evolution $\delta m$ in (\ref{eq:deltam_vl_supp}). In the following we study separately the stability analysis for the anomalous correlator, and the normal correlators.
L002283	
L002284	\subsubsection{Stability analysis of the anomalous correlator, Eq.(\ref{eq:deltam_vl_supp})}
L002285	
L002286	We perform the stability analysis of the anomalous correlator by  introducing $\delta {\tilde m}(\Omega,\omega,z)=\int \delta m(t,\omega,z)\exp(-i\Omega t) dt$, we obtain from Eq.(\ref{eq:m_vl_supp})
L002287	\begin{align*}
L002288	i\partial_z \delta {\tilde m}(\Omega,\omega,z) =&
L002289	\big( 2\beta \omega \Omega + \gamma (2-\kappa)(N_y^0-N_x^0) -2 \alpha  \big)\delta {\tilde m}
L002290	\\
L002291	&+ \frac{\gamma \kappa}{2\pi}
L002292	\big(n_x^0(\omega)- n_y^0(\omega)-\frac{\Omega}{2}\partial_\omega n_y^{0}(\omega)-\frac{\Omega}{2}\partial_\omega n_x^{0}(\omega) \big)
L002293	 \int \big(  \delta {\tilde m}(\Omega,\omega_1,z) +  \delta {\tilde m}^*(-\Omega,\omega_1,z) \big) d\omega_1.
L002294	\end{align*}
L002295	To derive the dispersion relation, it proves convenient to introduce the function $\delta {\tilde p}(\Omega,\omega,z)=\delta {\tilde m}^*(\Omega,-\omega,z)$, which gives the system
L002296	\begin{align*}
L002297	i\partial_z \delta {\tilde m}(\Omega,\omega,z) =&
L002298	\big( 2\beta \omega \Omega + \gamma (2-\kappa)(N_y^0-N_x^0) -2 \alpha  \big)\delta {\tilde m}
L002299	\\
L002300	&+ \frac{\gamma \kappa}{2\pi}
L002301	\big(n_x^0(\omega)- n_y^0(\omega)-\frac{\Omega}{2}\partial_\omega n_y^0(\omega)-\frac{\Omega}{2}\partial_\omega n_x^0(\omega) \big)
L002302	 \int \big(  \delta {\tilde m}(\Omega,\omega_1,z) +  \delta {\tilde p}(\Omega,\omega_1,z) \big) d\omega_1   , \\
L002303	-i\partial_z \delta {\tilde p}(\Omega,\omega,z) =&
L002304	\big( -2\beta \omega \Omega + \gamma (2-\kappa)(N_y^0-N_x^0) -2 \alpha  \big)\delta {\tilde m}
L002305	\\
L002306	&+ \frac{\gamma \kappa}{2\pi}
L002307	\big(n_y^0(\omega)- n_x^0(\omega)+\frac{\Omega}{2}\partial_\omega n_y^0(\omega)+\frac{\Omega}{2}\partial_\omega n_x^0(\omega) \big)
L002308	 \int \big(  \delta {\tilde m}(\Omega,\omega_1,z) +  \delta {\tilde p}(\Omega,\omega_1,z) \big) d\omega_1   .
L002309	\end{align*}
L002310	Introducing the Laplace transforms of the anomalous correlator
L002311	$\delta {\hat m}(\Omega,\omega,\lambda)=\int_0^z ds \delta {\tilde m}(\Omega,\omega,s) \exp(-\lambda s)$, $\delta {\hat p}(\Omega,\omega,\lambda)=\int_0^z ds \delta {\tilde p}(\Omega,\omega,s) \exp(-\lambda s)$, we obtain the dispersion relation for the instability growth-rate of the anomalous correlator ${\rm Re}[\lambda(\Omega)]$:
L002312	\begin{eqnarray}
L002313	\frac{2\pi}{\gamma\kappa} = \int
L002314	\frac{n_x^0(\omega)-n_y^0(\omega)-(\Omega/2)\partial_\omega \big(n_x^0(\omega)+n_y^0(\omega)\big)}{i \lambda-2\beta\omega \Omega - \gamma(2-\kappa)(N_y^0-N_x^0)+2\alpha}
L002315	+\frac{n_x^0(\omega)-n_y^0(\omega)+(\Omega/2)\partial_\omega \big(n_x^0(\omega)+n_y^0(\omega)\big)}{-i \lambda+2\beta\omega \Omega - \gamma(2-\kappa)(N_y^0-N_x^0)+2\alpha}
L002316	d\omega.
L002317	\label{eq:disp_rel_supp}
L002318	\end{eqnarray}
L002319	We have considered initial Gaussian spectra of the form: $n_\mu^0(\omega)=\frac{\sqrt{2\pi}}{\sigma} N_\mu^0 \exp(-\omega^2/(2 \sigma^2))$. The analysis shows that, in general, ${\rm Re}[\lambda(\Omega)]$ is peaked on $\Omega=0$, i.e., the homogeneous mode is the most unstable. Note in this respect that the growth-rate of the homogeneous mode does not depend on the initial spectrum: Regardless of the particular form of $n_\mu^0(\omega)$, the growth-rate for the homogeneous mode reads:
L002320	\begin{equation}
L002321	\lambda(\Omega=0)=
L002322	 \sqrt{\big(\gamma(2-\kappa)\Delta N^0-2\alpha\big)\big( \gamma(3\kappa-2)\Delta N^0+2\alpha\big)}.
L002323	\end{equation}
L002324	Note that this expression recovers Eq.(6) (main text) for $\kappa=2/3$.
L002325	
L002326	Fig.~\ref{fig:stability} shows the influence of the various parameters on $\rm{Re}[\lambda]$. We can see that in most cases, the maximum growth, i.e. the maximum of $\rm{Re}[\lambda]$, is achieved for $\Omega = 0$. Increasing the spectral width, $\sigma$, reduces the range of frequencies $\Omega$ that are unstable without changing the maximum instability rate. Decreasing the initial power difference, $\Delta N^0$, reduces both the range of unstable modes $\Omega$ and the instability growth-rate. The influence of $\alpha$ is more subtle and reducing $\alpha$ can lead to a shift of the maximum instability rate from $\Omega = 0$ to $\Omega \neq 0$.
L002327	\begin{figure}[!h]
L002328	    \centering
L002329	    \includegraphics[width=0.95\linewidth]{figures/supplemental_stability.pdf}
L002330	    \caption{
L002331	    \baselineskip 10pt
L002332	    \textbf{Impact of the various parameters on $\rm{Re}[\lambda]$.}
L002333	
L002334	    Panel (a) shows the influence of varying $\alpha L_{nl}$ while keeping $\Delta N^0/N=1$ and $\sigma \tau_0 = 2 \pi$. Panel (b) shows the influence of varying $\Delta N^0/N$ while keeping $\alpha L_{nl}=1/3$ and $\sigma \tau_0 = 2 \pi $. Panel (c) shows the influence of varying $\sigma \tau_0$ while keeping $\alpha L_{nl}=1/3$ and $\Delta N^0 /N= 1$.}
L002335	    \label{fig:stability}
L002336	\end{figure}
L002337	\subsubsection{Stability analysis of the normal correlators, Eqs.(\ref{eq:deltanx_vl_supp}-\ref{eq:deltany_vl_supp})}
L002338	
L002339	Following a procedure similar to that for the anomalous correlator, we now carry out the stability analysis for the normal correlators whose evolution is governed by the linearized Eqs.(\ref{eq:deltanx_vl_supp}-\ref{eq:deltany_vl_supp}).
L002340	Defining $\delta {\hat n}_\mu(\Omega,\omega,\lambda_n)=\int_0^z ds \int dt \delta {n}_\mu(t,\omega,z) \exp(-i\Omega t -\lambda_n s)$, we obtain the set of coupled equations:
L002341	\begin{align}
L002342	\delta {\hat n}_x(\Omega,\omega,\lambda_n) &=
L002343	\frac{i\gamma \Omega \partial_\omega n_x^0(\omega)}{2\pi(\lambda_n + 2 i \beta \omega \Omega)}
L002344	\int  2\delta {\hat n}_x(\Omega,\omega_1,\lambda_n)+\kappa \delta {\hat n}_y(\Omega,\omega_1,\lambda_n) d\omega_1,\\
L002345	\delta {\hat n}_y(\Omega,\omega,\lambda_n) &=
L002346	\frac{i\gamma \Omega \partial_\omega n_y^0(\omega)}{2\pi(\lambda_n + 2 i \beta \omega \Omega)}
L002347	\int  2\delta {\hat n}_y(\Omega,\omega_1,\lambda_n)+\kappa \delta {\hat n}_x(\Omega,\omega_1,\lambda_n) d\omega_1,
L002348	\end{align}
L002349	The dispersion relation $\lambda_n(\Omega)$ for the normal correlator is obtained by solving the integral equation:
L002350	\begin{align}
L002351	&\big(1-2{\cal I}_x(\Omega,\lambda_n) \big) \big(1-2{\cal I}_y(\Omega,\lambda_n) \big)=\kappa^2 {\cal I}_x(\Omega,\lambda_n) {\cal I}_y(\Omega,\lambda_n),
L002352	\label{eq:lambda_n}
L002353	\end{align}
L002354	where the integrals ${\cal I}_\mu(\Omega,\lambda_n)$ are given by
L002355	\begin{align}
L002356	{\cal I}_\mu(\Omega,\lambda_n)=\frac{i\gamma \Omega }{2\pi}\int \frac{\partial_\omega n_\mu^0(\omega)}{\lambda_n + 2 i \beta \omega \Omega} d\omega = -\frac{\gamma \beta \Omega^2 }{\pi}\int \frac{n_\mu^0(\omega)}{(\lambda_n + 2 i \beta \omega \Omega)^2} d\omega, \quad \mu=x,y.
L002357	\end{align}
L002358	We consider initial Gaussian spectra of the form: $n_\mu^0(\omega)=\frac{\sqrt{2\pi}}{\sigma} N_\mu^0 \exp(-\omega^2/(2 \sigma^2))$. We have solved numerically Eq.(\ref{eq:lambda_n}) to compute the dispersion relation $\lambda_n(\Omega)$. In the weakly nonlinear regime verifying $L_{lin} \sim (\beta \sigma^2)^{-1} \ll L_{nl} \sim (\gamma N)^{-1}$, the numerical analysis shows that the normal correlator is always stable, ${\rm Re}\big(\lambda_n(\Omega)\big) <0$.
L002359	
L002360	\subsection{Nonlinear dynamics with homogeneous statistics: Derivation of Eq.(8) (main text)}
L002361	
L002362	The analysis of the dispersion relation has revealed that, in general, the homogeneous mode $\Omega=0$ is the most unstable mode, see Fig.~\ref{fig:stability}. Here, we analyze the nonlinear dynamics of Eq.(\ref{eq:nx_vl_supp}-\ref{eq:m_vl_supp}) in the limit of stationary statistics:
L002363	\begin{align}
L002364	\partial_z n_x(\omega,z) =& +4 \gamma\kappa M^r m^i(\omega)  ,
L002365	\label{eq:nx_vl_stat} \\
L002366	\partial_z n_y(\omega,z) =& -4 \gamma\kappa M^r m^i(\omega)  ,
L002367	\label{eq:ny_vl_stat} \\
L002368	\partial_z m(\omega,z) =&
L002369	-i  \big( \gamma(2-\kappa)(N_y-N_x)-2\alpha   \big) m
L002370	- 2i\gamma\kappa \big( n_x - n_y \big) M^r .
L002371	\label{eq:m_vl_stat}
L002372	\end{align}
L002373	Note that, $\left< {\tilde u}_y(\omega_1,z) {\tilde u}_x^*(\omega_2,z) \right>=2\pi m(\omega_1,z) \delta(\omega_1-\omega_2)$ under the assumption of homogeneous statistics (${\tilde u}_\mu(\omega,z)=\int u_\mu(t,z) \exp(-i\omega t) dt$ being the Fourier transform of the field), so that anomalous correlations between $u_x$ and $u_y$ arise only at the same frequency.
L002374	
L002375	By integration over $\omega$, we get the following system for the normal and anomalous correlators:
L002376	\begin{align}
L002377	\partial_z \Delta N &= -8 \gamma \kappa M^r M^i ,
L002378	\label{eq:DelaN_red}\\
L002379	\partial_z M^r &= \big( \gamma (2- \kappa)\Delta N -2\alpha \big) M^i ,
L002380	\label{eq:Mr_red}\\
L002381	\partial_z M^i &= - \big(\gamma (2- 3 \kappa)\Delta N -2\alpha \big) M^r .
L002382	\label{eq:Mi_red}
L002383	\end{align}
L002384	where $\Delta N(z)=N_y(z)-N_x(z)$, and we recall that $N_\mu(z) = \frac{1}{2\pi}\int n_\mu(\omega,z) d\omega$, $M(z) = \frac{1}{2\pi}\int m(\omega,z) d\omega$.
L002385	Introducing the Stokes vector ${\bm S}(z)=\big( \Delta N(z), 2 M^r(z), 2 M^i(z) \big)^T$, the dynamics (\ref{eq:DelaN_red}-\ref{eq:Mi_red}) can be recast as a rotation of this vector on the Poincar\'e sphere (see Eq.(8) in the main text):
L002386	\begin{align}
L002387	&\partial_z {\bm S}(\tau,z) = {\bm R}(z) \times  {\bm S}(z),
L002388	\label{eq:S_dyn}\\
L002389	&{\bm R}(z) = \big( 2\alpha-\gamma (2-\kappa) S_1(z), \ -2\gamma \kappa S_2(z), \ 0  \big)^T.
L002390	\label{eq:S_R_dyn}
L002391	\end{align}
L002392	Because ${\bm S}.\partial_z {\bm S}=0$, the vector ${\bm S}(z)$ evolves on the surface of the Poincar\'e sphere of constant radius
L002393	\begin{align}
L002394	S_0=\Big( \sum_{j=1}^3 S_j^2  \Big)^{1/2}=\sqrt{\Delta N(z)^2 + 4|M(z)|^2}= {\rm const}.
L002395	\label{eq:S_0}
L002396	\end{align}
L002397	Consequently, the degree of polarization is conserved during  evolution,  ${\cal P}(z)=S_0/N=$const.
L002398	
L002399	Considering the case $\kappa=2/3$ relevant to our experiments: The fixed point $S_1=-S_0$ is stable. Conversely, as discussed in the main text through Eq.(8), the fixed point $S_1=+S_0$ becomes unstable for $\alpha < \alpha_c = \frac{2}{3}\gamma S_1$, giving rise to two new stable fixed points located at $S_1=3\alpha/(2\gamma), S_2=0, S_3=\pm \sqrt{S_0^2-S_1^{2}}$.
L002400	
L002401	
L002402	
L002403	The Poincar\'e–Stokes formalism employed here differs fundamentally from the one commonly used to describe the polarization dynamics of fully coherent stationary waves \cite{agrawal}. First, the Stokes vector represents the  correlation functions of an incoherent random wave, rather than the coherent field amplitudes. Second, in the  coherent stationary case, the radius of the Poincar\'e sphere $S_0$, is determined solely by the total power $N$; consequently, all solutions with fixed power $N$ evolve on the surface of a single sphere. In contrast, in the present formulation the sphere radius also depends on the degree of polarization, $S_0 = {\cal P} N$. As a result, $S_0$ varies with the initial conditions even when the total power is held fixed ($N=$const): The full set of solutions is not described by a single sphere, but instead by an ensemble of spheres with different radii.
L002404	
